#include "ENGINE/Source/Anim/interp.h"
#include "ENGINE/Source/Anim/anim.h"
#include <stdexcept>
void CKeyFrameTrackBase::SetNumKeys(unsigned count,unsigned keySize){m_keyFrameSize=keySize;m_keyFrames.reserve(count);}
void CKeyFrameTrackBase::AddKey(int time){if(!m_keyFrames.empty()&&time<m_keyFrames.back().time)throw std::invalid_argument("animation keys must be ordered");m_keyFrames.push_back({time});}
void CKeyFrameTrackBase::SetSequenceIndices(unsigned s,unsigned start,unsigned count){if(m_indices.size()<=s)m_indices.resize(s+1);m_indices[s]={start,count};}
void CKeyFrameTrackBase::SetSequenceIndices(const std::vector<CAnimSequence>&sequences){if(m_globalSeqId!=~0U)return;m_indices.assign((std::max)(std::size_t{1},sequences.size()),{});if(sequences.empty()){m_indices[0]={0,static_cast<unsigned>(m_keyFrames.size())};return;}for(unsigned s=0;s<sequences.size();++s){const auto&sequence=sequences[s];unsigned first=0;while(first<m_keyFrames.size()&&m_keyFrames[first].time<sequence.start)++first;unsigned last=first;while(last<m_keyFrames.size()&&m_keyFrames[last].time<=sequence.end)++last;m_indices[s]={first,last-first};}}
unsigned CKeyFrameTrackBase::FindKeyForTime(unsigned s,int time)const{if(m_keyFrames.empty())return 0;CKeySeq range=s<m_indices.size()?m_indices[s]:CKeySeq{0,static_cast<unsigned>(m_keyFrames.size())};if(!range.count)return range.start;unsigned result=range.start;for(unsigned i=range.start;i<range.start+range.count&&i<m_keyFrames.size();++i){if(m_keyFrames[i].time>time)break;result=i;}return result;}
unsigned CKeyFrameTrackBase::FindKeyForTimeConstSeq(unsigned s,int t)const{return FindKeyForTime(s,t);}
unsigned CKeyFrameTrackBase::FindKeyForTime(unsigned s,unsigned current,int time)const{CKeySeq range=s<m_indices.size()?m_indices[s]:CKeySeq{0,static_cast<unsigned>(m_keyFrames.size())};if(!range.count)return range.start;if(current<range.start||current>=range.start+range.count||m_keyFrames[current].time>time)current=range.start;while(current+1<range.start+range.count&&m_keyFrames[current+1].time<=time)++current;return current;}
unsigned CKeyFrameTrackBase::FindKeyForTimeConstSeq(unsigned current,int time,bool)const{if(m_keyFrames.empty())return 0;if(current>=m_keyFrames.size()||m_keyFrames[current].time>time)current=0;while(current+1<m_keyFrames.size()&&m_keyFrames[current+1].time<=time)++current;return current;}
unsigned CKeyFrameTrackBase::NextKey(unsigned key,unsigned s)const{CKeySeq r=s<m_indices.size()?m_indices[s]:CKeySeq{0,static_cast<unsigned>(m_keyFrames.size())};if(!r.count)return key;return key+1<r.start+r.count?key+1:r.start;}
bool CKeyFrameTrackBase::SetAnimTime(unsigned s,int t,int,CKeyTrackStatus&st)const{if(m_keyFrames.empty())return false;const unsigned sequenceId=m_globalSeqId==~0U?s:0U;if(sequenceId>=m_indices.size()||m_indices[sequenceId].count==0)return false;st.currKey=FindKeyForTime(sequenceId,t);st.nextKey=NextKey(st.currKey,sequenceId);st.timepastkey=t-m_keyFrames[st.currKey].time;return true;}
bool CKeyFrameTrackBase::JustPastKeyForward(const CKeyTrackStatus&s,unsigned k)const{return s.currKey==k&&s.timepastkey>=0;}bool CKeyFrameTrackBase::JustPastKeyBackward(const CKeyTrackStatus&s,unsigned k)const{return s.nextKey==k&&s.timepastkey<=0;}bool CKeyFrameTrackBase::JustPastKey(const CKeyTrackStatus&s,unsigned k,bool f)const{return f?JustPastKeyForward(s,k):JustPastKeyBackward(s,k);}const CKeyFrame*CKeyFrameTrackBase::GetKeyFrame(unsigned k)const{return k<m_keyFrames.size()?&m_keyFrames[k]:nullptr;}int CKeyFrameTrackBase::TimeDiff(unsigned a,unsigned b)const{return a<m_keyFrames.size()&&b<m_keyFrames.size()?m_keyFrames[b].time-m_keyFrames[a].time:0;}int CKeyFrameTrackBase::TimeDiff(unsigned a,unsigned b,unsigned sequenceTime)const{int difference=TimeDiff(a,b);return difference<0?difference+static_cast<int>(sequenceTime):difference;}
float EvaluateCubicPolynomial(float a,float b,float c,float d,float t){return((a*t+b)*t+c)*t+d;}float Blend(float a,float b,float t){return a+(b-a)*t;}NTempest::C3Vector Blend(const NTempest::C3Vector&a,const NTempest::C3Vector&b,float t){return AnimLerp(a,b,t);}
